import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import * as TypedCachedApiClient from '../../utils/TypedCachedApiClient';
import { ProblemId } from '../../interfaces/Problem';
import {
  SolvedProblem,
} from '../../interfaces/SolvedProblem';
import { langDisplayNames } from '../../components/NavigationBar';

export const SortedProblemIds: React.FC = () => {
  const { param, user, lang } = useParams() as {
    param: TypedCachedApiClient.UserParam;
    user: string;
    lang: string;
  };
  const [sortedProblems, setSortedProblems] = useState<[string, number][]>([]);
  const [solvedProblemsMap, setSolvedProblemsMap] = useState<Map<
    ProblemId,
    SolvedProblem
  > | null>(null);
  const targetUserId = user ?? 'default_user_id'; // fallback
  const [problemNameMap, setProblemNameMap] = useState<Map<
    ProblemId,
    string
  > | null>(null);
  const [problemLevelMap, setProblemLevelMap] = useState<Map<
    ProblemId,
    number
  > | null>(null);

  useEffect(() => {
    // 問題データ (スコア) の読み込み
    fetch(`${process.env.PUBLIC_URL}/data/${lang}.json`)
      .then((res) => res.json())
      .then((data: Record<string, number>) => {
        const sorted = Object.entries(data).sort((a, b) => a[1] - b[1]); // スコア昇順
        setSortedProblems(sorted);
      })
      .catch((err) => {
        console.error('スコアデータ読み込み失敗:', err);
        setSortedProblems([]);
      });

      // ユーザーの解決済み問題データ、全問題データ、難易度データの読み込みを並列で実行
    const fetchData = async () => {
      try {
        const [solvedMap, problems] = await Promise.all([
          TypedCachedApiClient.cachedSolvedProblemMap(param, targetUserId),
          TypedCachedApiClient.cachedProblemArray(),
        ]);

        setSolvedProblemsMap(solvedMap);

        const nameMap = new Map<ProblemId, string>();
        const levelMap = new Map<ProblemId, number>();
        problems.forEach((p) => {
          nameMap.set(p.ProblemId, p.Title);
          levelMap.set(p.ProblemId, p.Level);
        });
        setProblemNameMap(nameMap);
        setProblemLevelMap(levelMap);
      } catch (e) {
        console.error('データ読み込み失敗:', e);
        setSolvedProblemsMap(new Map());
        setProblemNameMap(new Map());
        setProblemLevelMap(new Map());
      }
    };

    void fetchData();
  }, [targetUserId, param, lang]);
  const totalProblems = sortedProblems.length;
  const visibleProblems = sortedProblems.filter(([id]) => {
    const problemIdNum = Number(id);
    return !(
      solvedProblemsMap &&
      !isNaN(problemIdNum) &&
      solvedProblemsMap.has(problemIdNum)
    );
  });
  return (
    <div>
      <h3>実装量順の問題ID一覧</h3>
      <p>
        ✅ AC 済みを除外しました。{langDisplayNames[lang] || lang} で誰かの AC がある {totalProblems}{' '}
        問中 {visibleProblems.length} 問を表示中。2025/6/1 までのデータ。
      </p>
      <ol>
        {sortedProblems.map(([id, length]) => {
          const problemIdNum: ProblemId = Number(id);
          const isSolvedByTargetUser =
            solvedProblemsMap && !isNaN(problemIdNum)
              ? solvedProblemsMap.has(problemIdNum)
              : false;
          const problemName = problemNameMap
            ? problemNameMap.get(problemIdNum)
            : '(問題名取得中...)';
          const problemLevel = problemLevelMap
            ? problemLevelMap.get(problemIdNum)
            : undefined;
          if (isSolvedByTargetUser) return null;
          // <DifficultyStars level={problemLevel} showDifficultyLevel={true} color={true} />で星を表示
          return (
            <li key={id}>
              <span>Level: {problemLevel}</span>
              <a href={`https://yukicoder.me/problems/${id}`}>
                {problemName}
              </a>{' '}
              - {length} bytes{' '}
              {solvedProblemsMap === null ? (
                <span>(解決状況を確認中...)</span>
              ) : (
                ''
              )}
            </li>
          );
        })}
      </ol>
    </div>
  );
};
